// concurrencyLimit is the maximum number of packages operated on at once.
const concurrencyLimit = 16

// Op is the per-package operation to run. Progress is reported by sending
// to the completion channel.
type Op func(ctx context.Context, p pkg.Package, completion chan<- pkg.Status) error

// Options configures a Run.
type Options struct {
	// Name is the operation name used in log messages, e.g. "install".
	Name string

	// Method is the name of the pkg.Package method being invoked,
	// used in the start log message, e.g. "Install".
	Method string

	// Canceled names the operation in cancellation errors,
	// e.g. "installation".
	Canceled string

	// Op is the operation to run for each package.
	Op Op

	// OnResult, if not nil, is called after each package's Op completes
	// with the package and the error returned by Op (nil on success).
	OnResult func(ctx context.Context, p pkg.Package, err error)
}

// result holds the outcome of running Op for a single package.
type result struct {
	Package pkg.Package
	Error   error
}

// Run executes opts.Op for each of pkgs concurrently, limited to
// concurrencyLimit packages at a time, while printing progress. It returns
// all errors that occurred combined into one error, or nil if every
